package org.eclipse.kura.core.keystore;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;

import java.io.File;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;
import java.util.Arrays;

import org.junit.Rule;
import org.junit.rules.TemporaryFolder;

public abstract class AbstractAtomicFileWriterTest {

    @Rule
    public TemporaryFolder folder = new TemporaryFolder();

    protected AtomicFileWriter writer = new AtomicFileWriter();
    protected Path target;
    protected Exception exception;

    protected void givenFile(final String name, final String content) throws IOException {
        Files.write(new File(this.folder.getRoot(), name).toPath(), content.getBytes(StandardCharsets.UTF_8));
    }

    protected void givenDirectory(final String name) throws IOException {
        Files.createDirectory(new File(this.folder.getRoot(), name).toPath());
    }

    protected void givenNullTarget() {
        this.target = null;
    }

    protected void givenTargetFile(final String name) {
        this.target = new File(this.folder.getRoot(), name).toPath();
    }

    protected void givenTargetFile(final String name, final String content) throws IOException {
        givenTargetFile(name);
        Files.write(this.target, content.getBytes(StandardCharsets.UTF_8));
    }

    protected void givenTargetDirectory(final String name) throws IOException {
        givenTargetFile(name);
        Files.createDirectory(this.target);
    }

    protected void thenNoExceptionIsThrown() {
        assertNull(this.exception);
    }

    protected void thenExceptionIsThrown(final Class<? extends Exception> expectedType) {
        assertTrue("expected " + expectedType.getSimpleName() + " but was " + this.exception,
                expectedType.isInstance(this.exception));
    }

    protected void thenFileContains(final String name, final String expected) throws IOException {
        final Path file = new File(this.folder.getRoot(), name).toPath();
        assertTrue(name + " should exist", Files.isRegularFile(file));
        assertEquals(expected, new String(Files.readAllBytes(file), StandardCharsets.UTF_8));
    }

    protected void thenDirectoryContainsOnly(final String... expectedNames) {
        final String[] actualNames = this.folder.getRoot().list();
        Arrays.sort(actualNames);
        Arrays.sort(expectedNames);
        assertEquals(Arrays.asList(expectedNames), Arrays.asList(actualNames));
    }
}
